look.customCSS:
/* ───── 八角 · 墨金 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/60px 60px,radial-gradient(ellipse at 50% 30%,#1F1B14,#12100D 70%) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：墨底，下沿一条细回纹金带 */
[data-wk="chathead"]{background:linear-gradient(180deg,#0C0B09,#1D1A15) !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;overflow:visible !important;gap:6px !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:100% !important;height:8px !important;background:url("data:image/svg+xml;base64,") 0 0/16px 8px repeat-x !important;pointer-events:none !important;opacity:.85 !important}
[data-wk="chathead"]::before{content:none !important}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:8px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#EBD394 !important;letter-spacing:.06em !important}
[data-wk="headdim"]{color:#9C8B66 !important;white-space:nowrap !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#C9A45C !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/32px no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/32px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：切成八角，外面一圈八角金框，四个斜角嵌金珠 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:0 !important;box-shadow:none !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:0 !important;clip-path:polygon(29% 0,calc(100% - 29%) 0,100% 29%,100% calc(100% - 29%),calc(100% - 29%) 100%,29% 100%,0 calc(100% - 29%),0 29%) !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-6% !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMDAgMTAwJz48cGF0aCBkPSdNMzAgMyBINzAgTDk3IDMwIFY3MCBMNzAgOTcgSDMwIEwzIDcwIFYzMFonIGZpbGw9J25vbmUnIHN0cm9rZT0nI0M5QTQ1Qycgc3Ryb2tlLXdpZHRoPSczLjInIHN0cm9rZS1saW5lam9pbj0ncm91bmQnLz48L3N2Zz4=") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important;border:none !important;border-radius:0 !important}

/* 顶栏头像也套八角金框 */
[data-wk="chathead"] button:has(> img[data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> img[data-wk="avatar"])::before{content:"" !important;position:absolute !important;left:-3px !important;top:50% !important;width:42px !important;height:42px !important;margin:-21px 0 0 0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMDAgMTAwJz48cGF0aCBkPSdNMzAgMyBINzAgTDk3IDMwIFY3MCBMNzAgOTcgSDMwIEwzIDcwIFYzMFonIGZpbGw9J25vbmUnIHN0cm9rZT0nI0M5QTQ1Qycgc3Ryb2tlLXdpZHRoPSczLjInIHN0cm9rZS1saW5lam9pbj0ncm91bmQnLz48L3N2Zz4=") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important}

/* 气泡：八角牌。外层画金边，::before 垫里面那块底（比外层缩进一圈） */
[data-wk="bubble"][data-kind="text"]{position:relative !important;isolation:isolate !important;border:none !important;border-radius:0 !important;clip-path:polygon(8px 0,calc(100% - 8px) 0,100% 8px,100% calc(100% - 8px),calc(100% - 8px) 100%,8px 100%,0 calc(100% - 8px),0 8px) !important;box-shadow:none !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;inset:1.6px !important;clip-path:polygon(7.4px 0,calc(100% - 7.4px) 0,100% 7.4px,100% calc(100% - 7.4px),calc(100% - 7.4px) 100%,7.4px 100%,0 calc(100% - 7.4px),0 7.4px) !important;z-index:-1 !important;border:none !important;transform:none !important;width:auto !important;height:auto !important;top:1.6px !important;left:1.6px !important;right:1.6px !important;bottom:1.6px !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
/* 我的话：金牌，墨字 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#8A6A2E !important;color:#12100D !important;font-weight:500 !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{background:linear-gradient(180deg,#E3C47E,#C9A45C 55%,#B8944D) !important}
/* 他的话：墨底金边 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#C9A45C !important;color:#F2E6C8 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{background:linear-gradient(180deg,#262119,#1D1A15) !important}

/* 时间：两道细金线夹两颗空心菱形 */
[data-wk="time"]{display:flex !important;justify-content:center !important}
[data-wk="time"] > span{display:inline-flex !important;align-items:center !important;justify-content:center !important;gap:8px !important;background:transparent !important;border:none !important;color:#C9A45C !important;font-family:serif !important;letter-spacing:.15em !important;font-size:12px !important;box-shadow:none !important;padding:2px 0 !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;display:inline-block !important;width:64px !important;height:10px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgMS4yIEwxMC44IDYgTDYgMTAuOCBMMS4yIDZaJyBmaWxsPSdub25lJyBzdHJva2U9JyNDOUE0NUMnIHN0cm9rZS13aWR0aD0nMS4zJy8+PC9zdmc+") right center/10px 10px no-repeat,linear-gradient(#8A6A2E,#8A6A2E) left center/calc(100% - 14px) 1px no-repeat !important}
[data-wk="time"] > span::after{transform:scaleX(-1) !important}
/* 已读：一枚八角小金印刻「阅」；已送达只留一行小字 */
[data-wk="meta"]{color:#9C8B66 !important;font-size:10.5px !important;font-family:serif !important;letter-spacing:.08em !important}
[data-wk="meta"]{display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"][data-read="1"]::before{content:"" !important;display:inline-block !important;width:15px !important;height:15px !important;flex:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;order:-1 !important}
[data-wk="meta"][data-read="0"]::after{content:"" !important;display:inline-block !important;width:15px !important;height:15px !important;flex:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#1D1A15 !important;border:1.4px solid #C9A45C !important;border-radius:0 !important;clip-path:polygon(9px 0,calc(100% - 9px) 0,100% 9px,100% calc(100% - 9px),calc(100% - 9px) 100%,9px 100%,0 calc(100% - 9px),0 9px) !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{width:8px !important;height:8px !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgLjggTDExLjIgNiBMNiAxMS4yIEwuOCA2WicgZmlsbD0nI0M5QTQ1Qycgc3Ryb2tlPScjRUJEMzk0JyBzdHJva2Utd2lkdGg9JzEnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="name"]{color:#C9A45C !important}

/* 动描：不进框——上下两道往两头淡出的金线，正中断开嵌菱形（上实下空），字是正体、字距松 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{position:relative !important;display:block !important;background:linear-gradient(90deg,transparent,#8A6A2E 25%,#8A6A2E calc(50% - 12px),transparent calc(50% - 12px),transparent calc(50% + 12px),#8A6A2E calc(50% + 12px),#8A6A2E 75%,transparent) center top/100% 1px no-repeat,linear-gradient(90deg,transparent,#8A6A2E 25%,#8A6A2E calc(50% - 12px),transparent calc(50% - 12px),transparent calc(50% + 12px),#8A6A2E calc(50% + 12px),#8A6A2E 75%,transparent) center bottom/100% 1px no-repeat !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#CDBE9C !important;font-style:normal !important;font-family:serif !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.12em !important;padding:16px 22px !important;text-align:center !important}
[data-wk="narrink"]::before{content:"" !important;position:absolute !important;left:50% !important;top:-5px !important;width:10px !important;height:10px !important;margin-left:-5px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgLjggTDExLjIgNiBMNiAxMS4yIEwuOCA2WicgZmlsbD0nI0M5QTQ1Qycgc3Ryb2tlPScjRUJEMzk0JyBzdHJva2Utd2lkdGg9JzEnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="narrink"]::after{content:"" !important;position:absolute !important;left:50% !important;bottom:-5px !important;width:10px !important;height:10px !important;margin-left:-5px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgMS4yIEwxMC44IDYgTDYgMTAuOCBMMS4yIDZaJyBmaWxsPSdub25lJyBzdHJva2U9JyNDOUE0NUMnIHN0cm9rZS13aWR0aD0nMS4zJy8+PC9zdmc+") center/contain no-repeat !important}
/* 系统提示：不带框的一行小字，前面一颗空心金菱 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9C8B66 !important;font-size:11.5px !important;font-style:normal !important;font-family:serif !important;letter-spacing:.08em !important}
[data-wk="sysnotetext"]::before{content:"" !important;display:inline-block !important;width:9px !important;height:9px !important;margin-right:6px !important;vertical-align:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgMS4yIEwxMC44IDYgTDYgMTAuOCBMMS4yIDZaJyBmaWxsPSdub25lJyBzdHJva2U9JyNDOUE0NUMnIHN0cm9rZS13aWR0aD0nMS4zJy8+PC9zdmc+") center/contain no-repeat !important}
[data-wk="sysnoteclose"]{color:#9C8B66 !important}

/* 底栏：墨底，上沿一条回纹金带；输入框是墨底金边的长八角 */
[data-wk="composer"]{background:#1D1A15 !important;border-top:none !important;position:relative !important;overflow:visible !important;align-items:center !important;gap:8px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:-5px !important;height:10px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTYgMS4yIEwxMC44IDYgTDYgMTAuOCBMMS4yIDZaJyBmaWxsPSdub25lJyBzdHJva2U9JyNDOUE0NUMnIHN0cm9rZS13aWR0aD0nMS4zJy8+PC9zdmc+") center/10px 10px no-repeat,linear-gradient(90deg,#8A6A2E calc(50% - 9px),transparent calc(50% - 9px),transparent calc(50% + 9px),#8A6A2E calc(50% + 9px)) center/100% 1px no-repeat !important;pointer-events:none !important}
[data-wk="chatinput"]{background:#1A1712 !important;border:1.4px solid #8A6A2E !important;border-radius:9px !important;color:#F2E6C8 !important}
[data-wk="chatinput"]::placeholder{color:#9C8B66 !important}
[data-wk="chatplus"],[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:36px !important;min-width:36px !important;height:36px !important;border:none !important;border-radius:0 !important;box-shadow:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:#1D1A15 !important;border-top:1.4px solid #8A6A2E !important}
